print_stmt_if_then_set(if_then_set(Var260,Val261,In263), T265) :- print_expr(Val261, 0, T262), print_rule_dsname(In263, T264), flatten([['if'], [Var260], ['='], T262, ['then'], ['set'], T264, [';']], T265).
