print_stmt_merge(merge(L289), T291) :- cl_13(L289, T290), flatten([['merge'], T290, [';']], T291).
print_stmt(T, Texts) :- print_stmt_merge(T, Texts), !.

print_stmt_by(by(L297), T299) :- cl_15(L297, T298), flatten([['by'], T298, [';']], T299).
